#!/usr/bin/env bash
set -euo pipefail
DEST="${ECC_DEST:-$HOME/vhdl_repo/IP_Cores/ECC_Scrubber}"
mkdir -p "$DEST"
echo ">> destino: $DEST"
echo "" | base64 -d > "$DEST/ecc_oracle.py"
echo "" | base64 -d > "$DEST/test_oracle.py"
echo "" | base64 -d > "$DEST/gen_layer1_vectors.py"
echo ">> corriendo autotests del oraculo"
( cd "$DEST" && python3 test_oracle.py )
echo ">> generando vectores Layer 1"
( cd "$DEST" && python3 gen_layer1_vectors.py )
echo ">> archivos en $DEST:"
ls -l "$DEST"
